<?php
declare(strict_types=1);
date_default_timezone_set('Europe/Berlin');
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';
ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');
session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();
header('Cache-Control: no-store, private');
require_once dirname(__DIR__).'/app/bootstrap.php';
require_once dirname(__DIR__).'/app/document_storage.php';
function invoiceSettingsH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;
if(!is_array($user)||($user['role']??'')!=='coach'){http_response_code(403);exit('Rechnungseinstellungen sind Coaches vorbehalten.');}
$db=coachingDatabase();$coach=(int)$user['id'];$token=$_SESSION['csrf_token']??'';
if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$defaults=['absender_name'=>'','absender_strasse'=>'','absender_plz'=>'','absender_ort'=>'','absender_land'=>'','absender_email'=>'','absender_telefon'=>'','steuernummer'=>'','umsatzsteuer_id'=>'','bank_inhaber'=>'','bank_name'=>'','bank_iban'=>'','bank_bic'=>'','barzahlung_aktiv'=>0,'ec_zahlung_aktiv'=>0,'standard_steuersatz_id'=>0,'standard_vorlage_id'=>0,'logo_speicher_schluessel'=>'','logo_mime'=>'','zahlungsziel_tage'=>14];
$q=$db->prepare('SELECT * FROM coaching_rechnungseinstellungen WHERE coach_benutzer_id=:coach');$q->execute(['coach'=>$coach]);$settings=array_merge($defaults,$q->fetch(PDO::FETCH_ASSOC)?:[]);
$error='';$notice=isset($_GET['saved'])?'Einstellungen gespeichert.':'';
function invoiceAddress(array $row):string{return implode("\n",array_values(array_filter([trim((string)($row['absender_strasse']??'')),trim((string)($row['absender_plz']??'').' '.(string)($row['absender_ort']??'')),trim((string)($row['absender_land']??''))],static fn(string $x):bool=>$x!=='')));}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($token,(string)($_POST['csrf_token']??''))){http_response_code(400);exit('Ungültige Anfrage.');}
 $action=(string)($_POST['action']??'');
 try{
  if($action==='profile'){
   $fields=['absender_name'=>190,'absender_strasse'=>190,'absender_plz'=>20,'absender_ort'=>100,'absender_land'=>100,'absender_email'=>190,'absender_telefon'=>40,'steuernummer'=>100,'umsatzsteuer_id'=>100,'bank_inhaber'=>190,'bank_name'=>190,'bank_iban'=>64,'bank_bic'=>32];
   $input=[];foreach($fields as $field=>$max){$v=trim((string)($_POST[$field]??''));if(strlen($v)>$max)throw new InvalidArgumentException('Ein Feld überschreitet die zulässige Länge.');$input[$field]=$v?:null;}
   if(($input['absender_email']??'')!==null&&!filter_var($input['absender_email'],FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Bitte eine gültige Absender-E-Mail-Adresse eingeben.');
   $due=filter_var($_POST['zahlungsziel_tage']??14,FILTER_VALIDATE_INT);if($due===false||$due<0||$due>365)throw new InvalidArgumentException('Das Zahlungsziel muss zwischen 0 und 365 Tagen liegen.');
   $cash=isset($_POST['barzahlung_aktiv'])?1:0;$ec=isset($_POST['ec_zahlung_aktiv'])?1:0;$taxId=(int)($_POST['standard_steuersatz_id']??0);$templateId=(int)($_POST['standard_vorlage_id']??0);
   if($taxId>0){$check=$db->prepare('SELECT id FROM coaching_steuersaetze WHERE id=:id AND coach_benutzer_id=:coach AND aktiv=1');$check->execute(['id'=>$taxId,'coach'=>$coach]);if(!$check->fetchColumn())throw new InvalidArgumentException('Der gewählte Standardsatz ist nicht verfügbar.');}
   if($templateId>0){$check=$db->prepare('SELECT id FROM coaching_rechnungsvorlagen WHERE id=:id AND coach_benutzer_id=:coach AND aktiv=1');$check->execute(['id'=>$templateId,'coach'=>$coach]);if(!$check->fetchColumn())throw new InvalidArgumentException('Die gewählte Vorlage ist nicht verfügbar.');}
   $logoKey=$settings['logo_speicher_schluessel']?:null;$logoMime=$settings['logo_mime']?:null;$upload=$_FILES['logo']??null;
   if(is_array($upload)&&(int)($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){
    if((int)($upload['size']??0)>2*1024*1024)throw new InvalidArgumentException('Das Logo darf höchstens 2 MB groß sein.');
    $stored=coachingStoreDocumentUpload($upload,['image/jpeg','image/png']);$logoKey=$stored['key'];$logoMime=$stored['mime'];
   }
   $input['logo_speicher_schluessel']=$logoKey;$input['logo_mime']=$logoMime;$input['barzahlung_aktiv']=$cash;$input['ec_zahlung_aktiv']=$ec;$input['standard_steuersatz_id']=$taxId?:null;$input['standard_vorlage_id']=$templateId?:null;$input['zahlungsziel_tage']=$due;
   $params=['coach'=>$coach]+$input;
   $sql='INSERT INTO coaching_rechnungseinstellungen (coach_benutzer_id,'.implode(',',array_keys($input)).') VALUES (:coach,'.implode(',',array_map(static fn(string $key):string=>':'.$key,array_keys($input))).') ON DUPLICATE KEY UPDATE '.implode(',',array_map(static fn(string $key):string=>$key.'=VALUES('.$key.')',array_keys($input)));
   $db->prepare($sql)->execute($params);header('Location: invoice-settings.php?saved=1');exit;
  }
  if($action==='add_tax'||$action==='save_tax'){
   $id=(int)($_POST['id']??0);$label=trim((string)($_POST['bezeichnung']??''));$rate=str_replace(',','.',trim((string)($_POST['prozentsatz']??'')));
   if($label===''||strlen($label)>100||!preg_match('/^\d{1,3}(?:\.\d{1,2})?$/',$rate)||(float)$rate>100)throw new InvalidArgumentException('Bitte Bezeichnung und einen Satz zwischen 0 und 100 Prozent eingeben.');
   if($action==='add_tax')$db->prepare('INSERT INTO coaching_steuersaetze (coach_benutzer_id,bezeichnung,prozentsatz) VALUES (:coach,:label,:rate)')->execute(['coach'=>$coach,'label'=>$label,'rate'=>number_format((float)$rate,2,'.','')]);
   else{$s=$db->prepare('UPDATE coaching_steuersaetze SET bezeichnung=:label,prozentsatz=:rate WHERE id=:id AND coach_benutzer_id=:coach');$s->execute(['label'=>$label,'rate'=>number_format((float)$rate,2,'.',''),'id'=>$id,'coach'=>$coach]);if($s->rowCount()===0){$check=$db->prepare('SELECT id FROM coaching_steuersaetze WHERE id=:id AND coach_benutzer_id=:coach');$check->execute(['id'=>$id,'coach'=>$coach]);if(!$check->fetchColumn())throw new InvalidArgumentException('Steuersatz nicht gefunden.');}}
   header('Location: invoice-settings.php?saved=1#tax');exit;
  }
  if($action==='toggle_tax'){
   $id=(int)($_POST['id']??0);$active=(int)($_POST['aktiv']??0)===1?1:0;
   $s=$db->prepare('UPDATE coaching_steuersaetze SET aktiv=:active WHERE id=:id AND coach_benutzer_id=:coach');$s->execute(['active'=>$active,'id'=>$id,'coach'=>$coach]);
   if(!$active)$db->prepare('UPDATE coaching_rechnungseinstellungen SET standard_steuersatz_id=NULL WHERE coach_benutzer_id=:coach AND standard_steuersatz_id=:id')->execute(['coach'=>$coach,'id'=>$id]);
   header('Location: invoice-settings.php?saved=1#tax');exit;
  }
  if($action==='add_template'||$action==='save_template'){
   $id=(int)($_POST['id']??0);$title=trim((string)($_POST['titel']??''));$head=trim((string)($_POST['kopftext']??''));$foot=trim((string)($_POST['fusszeile']??''));$text=trim((string)($_POST['auftragstext']??''));
   if($title===''||strlen($title)>190||strlen($head)>10000||strlen($foot)>10000||strlen($text)>10000)throw new InvalidArgumentException('Bitte Vorlagentitel und Textlängen prüfen.');
   if($action==='add_template')$db->prepare('INSERT INTO coaching_rechnungsvorlagen (coach_benutzer_id,titel,kopftext,fusszeile,auftragstext) VALUES (:coach,:title,:head,:foot,:body)')->execute(['coach'=>$coach,'title'=>$title,'head'=>$head?:null,'foot'=>$foot?:null,'body'=>$text?:null]);
   else{$s=$db->prepare('UPDATE coaching_rechnungsvorlagen SET titel=:title,kopftext=:head,fusszeile=:foot,auftragstext=:body WHERE id=:id AND coach_benutzer_id=:coach');$s->execute(['title'=>$title,'head'=>$head?:null,'foot'=>$foot?:null,'body'=>$text?:null,'id'=>$id,'coach'=>$coach]);if($s->rowCount()===0){$check=$db->prepare('SELECT id FROM coaching_rechnungsvorlagen WHERE id=:id AND coach_benutzer_id=:coach');$check->execute(['id'=>$id,'coach'=>$coach]);if(!$check->fetchColumn())throw new InvalidArgumentException('Vorlage nicht gefunden.');}}
   header('Location: invoice-settings.php?saved=1#templates');exit;
  }
  if($action==='delete_template'){
   $id=(int)($_POST['id']??0);$db->prepare('UPDATE coaching_rechnungseinstellungen SET standard_vorlage_id=NULL WHERE coach_benutzer_id=:coach AND standard_vorlage_id=:id')->execute(['coach'=>$coach,'id'=>$id]);
   $db->prepare('DELETE FROM coaching_rechnungsvorlagen WHERE id=:id AND coach_benutzer_id=:coach')->execute(['id'=>$id,'coach'=>$coach]);header('Location: invoice-settings.php?saved=1#templates');exit;
  }
  throw new InvalidArgumentException('Unbekannte Aktion.');
 }catch(InvalidArgumentException $e){$error=$e->getMessage();}
 catch(Throwable $e){error_log('Invoice settings save failed: '.$e->getMessage());$error='Einstellungen konnten nicht gespeichert werden. Prüfe Migration 013, Dateispeicher und Tabellenrechte.';}
}
$q=$db->prepare('SELECT * FROM coaching_rechnungseinstellungen WHERE coach_benutzer_id=:coach');$q->execute(['coach'=>$coach]);$settings=array_merge($defaults,$q->fetch(PDO::FETCH_ASSOC)?:[]);
$q=$db->prepare('SELECT id,bezeichnung,prozentsatz,aktiv FROM coaching_steuersaetze WHERE coach_benutzer_id=:coach ORDER BY aktiv DESC,bezeichnung');$q->execute(['coach'=>$coach]);$rates=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare('SELECT id,titel,kopftext,fusszeile,auftragstext,aktiv FROM coaching_rechnungsvorlagen WHERE coach_benutzer_id=:coach ORDER BY titel');$q->execute(['coach'=>$coach]);$templates=$q->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rechnungseinstellungen</title><link rel="stylesheet" href="assets/layout.css"><style>
.page{max-width:1080px;margin:auto;padding:32px clamp(20px,4vw,56px) 64px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#fff;border:1px solid #e4ebe6;border-radius:14px;padding:20px;margin:16px 0}.form{display:grid;gap:10px}.form label{display:grid;gap:5px;font-weight:600}.form input,.form textarea,.form select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #dce5df;border-radius:8px;font:inherit}.form textarea{min-height:76px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.button{background:#245c50;color:white;border:0;border-radius:8px;padding:10px 14px;font:inherit;cursor:pointer}.button.light{background:#edf5ef;color:#245c50}.notice,.error{padding:12px;border-radius:8px}.notice{background:#edf5ef}.error{background:#fff3f1}.row{border-top:1px solid #edf1ee;padding:12px 0}.hint{font-size:13px;color:#718078}fieldset{border:1px solid #e4ebe6;border-radius:10px;margin:0;padding:12px}@media(max-width:760px){.grid,.fields{grid-template-columns:1fr}}
</style></head><body class="has-app-sidebar"><?php require_once dirname(__DIR__).'/app/navigation.php';renderCoachingSidebar($user,'invoice-settings',$token);?><main class="page">
<h1>Rechnungseinstellungen</h1><p>Diese Angaben und Vorlagen gelten für deine künftigen Rechnungen. Bereits ausgestellte Rechnungen behalten ihren gespeicherten Stand.</p><?php if($notice):?><p class="notice"><?=invoiceSettingsH($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=invoiceSettingsH($error)?></p><?php endif;?>
<section class="card"><h2>Coach-Profil für Rechnungen</h2><form method="post" enctype="multipart/form-data" class="form"><input type="hidden" name="csrf_token" value="<?=invoiceSettingsH($token)?>"><input type="hidden" name="action" value="profile">
<div class="grid"><div><label>Absender / Coach / Firma<input name="absender_name" maxlength="190" value="<?=invoiceSettingsH($settings['absender_name'])?>" required></label><label>Straße und Hausnummer<input name="absender_strasse" maxlength="190" value="<?=invoiceSettingsH($settings['absender_strasse'])?>"></label><div class="fields"><label>PLZ<input name="absender_plz" maxlength="20" value="<?=invoiceSettingsH($settings['absender_plz'])?>"></label><label>Ort<input name="absender_ort" maxlength="100" value="<?=invoiceSettingsH($settings['absender_ort'])?>"></label></div><label>Land<input name="absender_land" maxlength="100" value="<?=invoiceSettingsH($settings['absender_land'])?>"></label><div class="fields"><label>E-Mail<input name="absender_email" type="email" maxlength="190" value="<?=invoiceSettingsH($settings['absender_email'])?>"></label><label>Telefon<input name="absender_telefon" maxlength="40" value="<?=invoiceSettingsH($settings['absender_telefon'])?>"></label></div><label>Steuernummer<input name="steuernummer" maxlength="100" value="<?=invoiceSettingsH($settings['steuernummer'])?>"></label><label>Umsatzsteuer-ID<input name="umsatzsteuer_id" maxlength="100" value="<?=invoiceSettingsH($settings['umsatzsteuer_id'])?>"></label></div>
<div><fieldset><legend>Bankverbindung</legend><label>Kontoinhaber<input name="bank_inhaber" maxlength="190" value="<?=invoiceSettingsH($settings['bank_inhaber'])?>"></label><label>Bankname<input name="bank_name" maxlength="190" value="<?=invoiceSettingsH($settings['bank_name'])?>"></label><label>IBAN<input name="bank_iban" maxlength="64" value="<?=invoiceSettingsH($settings['bank_iban'])?>"></label><label>BIC<input name="bank_bic" maxlength="32" value="<?=invoiceSettingsH($settings['bank_bic'])?>"></label></fieldset><label><input type="checkbox" name="barzahlung_aktiv" value="1" <?=$settings['barzahlung_aktiv']?'checked':''?>> Barzahlung als Zahlungsart erlauben</label><label><input type="checkbox" name="ec_zahlung_aktiv" value="1" <?=$settings['ec_zahlung_aktiv']?'checked':''?>> EC-Zahlung als Zahlungsart erlauben</label><label>Standard-Zahlungsziel (Tage)<input type="number" min="0" max="365" name="zahlungsziel_tage" value="<?=(int)$settings['zahlungsziel_tage']?>"></label><label>Logo (PNG/JPG, maximal 2 MB)<input type="file" name="logo" accept="image/png,image/jpeg"></label><p class="hint"><?=$settings['logo_speicher_schluessel']?'Ein privates Logo ist gespeichert.':'Noch kein Logo hinterlegt.'?> Ein neues Logo ersetzt nur den Standard für künftige Rechnungen.</p>
<label>Standardsatz<select name="standard_steuersatz_id"><option value="0">Bitte auswählen</option><?php foreach($rates as $rate):if((int)$rate['aktiv']!==1)continue;?><option value="<?=(int)$rate['id']?>" <?=(int)$settings['standard_steuersatz_id']===(int)$rate['id']?'selected':''?>><?=invoiceSettingsH($rate['bezeichnung'].' · '.$rate['prozentsatz'].' %')?></option><?php endforeach;?></select></label><label>Standardvorlage<select name="standard_vorlage_id"><option value="0">Keine Standardvorlage</option><?php foreach($templates as $tpl):if((int)$tpl['aktiv']!==1)continue;?><option value="<?=(int)$tpl['id']?>" <?=(int)$settings['standard_vorlage_id']===(int)$tpl['id']?'selected':''?>><?=invoiceSettingsH($tpl['titel'])?></option><?php endforeach;?></select></label></div></div><button class="button">Profil speichern</button></form></section>
<section id="tax" class="card"><h2>Veränderbare Steuersätze</h2><p class="hint">Du legst selbst die Bezeichnung und den Prozentsatz an. Änderungen gelten nur für neu erstellte Rechnungen; gespeicherte Rechnungen behalten ihren Satz.</p>
<?php foreach($rates as $rate):?><form class="row form" method="post"><input type="hidden" name="csrf_token" value="<?=invoiceSettingsH($token)?>"><input type="hidden" name="action" value="save_tax"><input type="hidden" name="id" value="<?=(int)$rate['id']?>"><div class="fields"><label>Bezeichnung<input name="bezeichnung" maxlength="100" value="<?=invoiceSettingsH($rate['bezeichnung'])?>"></label><label>Steuersatz (%)<input type="number" name="prozentsatz" min="0" max="100" step="0.01" value="<?=invoiceSettingsH($rate['prozentsatz'])?>"></label></div><p class="hint"><?=$rate['aktiv']?'Aktiv':'Inaktiv'?></p><div><button class="button light">Ändern</button></div></form><form method="post" class="row"><input type="hidden" name="csrf_token" value="<?=invoiceSettingsH($token)?>"><input type="hidden" name="action" value="toggle_tax"><input type="hidden" name="id" value="<?=(int)$rate['id']?>"><input type="hidden" name="aktiv" value="<?=$rate['aktiv']?0:1?>"><button class="button light"><?=$rate['aktiv']?'Steuersatz deaktivieren':'Steuersatz aktivieren'?> · <?=invoiceSettingsH($rate['bezeichnung'])?></button></form><?php endforeach;?>
<form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=invoiceSettingsH($token)?>"><input type="hidden" name="action" value="add_tax"><h3>Steuersatz hinzufügen</h3><div class="fields"><label>Bezeichnung<input name="bezeichnung" maxlength="100" required placeholder="Eigene Bezeichnung"></label><label>Prozentsatz<input type="number" name="prozentsatz" min="0" max="100" step="0.01" required></label></div><button class="button">Steuersatz hinzufügen</button></form></section>
<section id="templates" class="card"><h2>Rechnungstext-Vorlagen</h2><p class="hint">Vorlagen enthalten Kopftext, Fußzeile und Auftragstext. Platzhalter: {{coach_name}}, {{klient_name}}, {{auftrag}}, {{sitzungsdatum}}, {{rechnungsnummer}}, {{rechnungsdatum}}, {{nettobetrag}}, {{steuerbetrag}}, {{bruttobetrag}}.</p>
<?php foreach($templates as $tpl):?><form method="post" class="row form"><input type="hidden" name="csrf_token" value="<?=invoiceSettingsH($token)?>"><input type="hidden" name="action" value="save_template"><input type="hidden" name="id" value="<?=(int)$tpl['id']?>"><label>Vorlagenname<input name="titel" maxlength="190" value="<?=invoiceSettingsH($tpl['titel'])?>" required></label><div class="fields"><label>Kopftext<textarea name="kopftext" maxlength="10000"><?=invoiceSettingsH($tpl['kopftext']??'')?></textarea></label><label>Fußzeile<textarea name="fusszeile" maxlength="10000"><?=invoiceSettingsH($tpl['fusszeile']??'')?></textarea></label></div><label>Auftragstext / Leistungsbeschreibung<textarea name="auftragstext" maxlength="10000"><?=invoiceSettingsH($tpl['auftragstext']??'')?></textarea></label><div class="fields"><button class="button light">Vorlage speichern</button></div></form><form method="post" class="row"><input type="hidden" name="csrf_token" value="<?=invoiceSettingsH($token)?>"><input type="hidden" name="action" value="delete_template"><input type="hidden" name="id" value="<?=(int)$tpl['id']?>"><button class="button light" onclick="return confirm('Vorlage löschen? Bereits erstellte Rechnungen bleiben unverändert.');">Vorlage löschen: <?=invoiceSettingsH($tpl['titel'])?></button></form><?php endforeach;?>
<form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=invoiceSettingsH($token)?>"><input type="hidden" name="action" value="add_template"><h3>Neue Vorlage</h3><label>Vorlagenname<input name="titel" maxlength="190" required></label><div class="fields"><label>Kopftext<textarea name="kopftext" maxlength="10000"></textarea></label><label>Fußzeile<textarea name="fusszeile" maxlength="10000"></textarea></label></div><label>Auftragstext / Leistungsbeschreibung<textarea name="auftragstext" maxlength="10000"></textarea></label><button class="button">Vorlage anlegen</button></form></section>
</main></body></html>